    input  [7:0] in,
    output reg [7:0] pedge
);
    reg [7:0] d1;
    reg [7:0] d2;
    reg [7:0] pedge_reg;
    always @(posedge clk) begin
        d1 <= in;
        d2 <= d1;
        pedge_reg <= 8'h00;
        for (int i = 0; i < 8; i = i + 1) begin
            if (d1[i] & ~d2[i]) pedge_reg[i] <= 1'b1;
        end
    end
    assign pedge = pedge_reg;
endmodule

