module TopModule (
    input  clk,
    input  [7:0] in,
    output [7:0] pedge
);
    reg [7:0] last;
    wire [7:0] edges;
    assign pedge = edges;
    always @(posedge clk) last <= in;
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin: g
            assign edges[i] = in[i] & ~last[i];
        end
    endgenerate
endmodule

