// Detect positive edge of input signal for each bit in an 8-bit vector.
module TopModule(input clk, input [7:0] in, output reg [7:0] pedge);
    reg [7:0] in_d1;
    always @(posedge clk) begin
        in_d1 <= in;
        for (integer i = 0; i < 8; i = i + 1)
            pedge[i] <= in[i] & ~in_d1[i];
    end
endmodule

